script.source:
function self(H, actor, ctx) { return actor === ctx.carrier && actor; }
function ready(H, actor) {
  if (actor.system.health.resolve.value <= 0) return;
  return H.condition.set(actor, "ready", true);
}
async function unready(H, actor) {
  const { removeCondition } = await import("/systems/hollows/code/documents/actor/conditions.js");
  await removeCondition(actor, "ready", { skipReactionDispatch: true });
}
return {
  combat: { hook: "interceptor", event: "combat-start-hunter", matchCarrier: self, run: ready },
  guard: { hook: "onEvent", eventType: "guard", run: ready },
  support: { hook: "interceptor", event: "support-recovery", matchCarrier: self, run: ready },
  broken: {
    hook: "interceptor", event: "hunter-broken", matchCarrier: self,
    async run(H, actor) {
      if (!H.condition.has(actor, "ready")) return;
      await unready(H, actor);
      await H.chat.post(actor.name + " becomes Unready (Broken).", actor);
    },
  },
  removed: {
    hook: "interceptor", event: "weapon-removed",
    async run(H, actor) {
      if (!H.weapon.equipped(actor, "Armour")) await unready(H, actor);
    },
  },
};
